-- Content translation consistency (owner request 2026-11-12, check C):
-- 1) Azerbaijani unit abbreviations left inside other languages (sm, kq, mq, mkq, qr/qram, "/gün") replaced with
--    each language's own units (cm/см/სმ/سم, kg, mg, mcg/µg/мкг, g); vitamin doses localized in every language.
-- 2) Empty translations filled: 60 English daily mommy messages, pregnancy texts (en), nutrition targets (en),
--    baby tooth names (en/ru/tr/kk/de/ar), temperature labels (en/ru/tr), 3 vitamins (8 languages), safety items (ka).
-- 3) Pregnancy day 248: removed the sentence whose number was missing in every language ("orta hesabla  sm").
-- Each update applies only if the cells are unchanged since review (md5); the final check rolls back otherwise.
-- 253 rows, 957 cells. Tables already CDC enrolled and writer guarded: admin_recipes, baby_teeth_db, blog_posts, mommy_daily_messages, nutrition_targets, pregnancy_daily_content, pregnancy_day_notifications, safety_items, temperature_emojis, vitamins, weekly_tips.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '180s';
DO $$ BEGIN
  IF (SELECT count(*) FROM _anacan_gcp_migration.guarded_relations WHERE schema_name = 'public' AND table_name IN ('admin_recipes', 'baby_teeth_db', 'blog_posts', 'mommy_daily_messages', 'nutrition_targets', 'pregnancy_daily_content', 'pregnancy_day_notifications', 'safety_items', 'temperature_emojis', 'vitamins', 'weekly_tips')) <> 11 THEN
    RAISE EXCEPTION 'CONTENT_FIX_GUARD_MISSING'; END IF;
END $$;

