UPDATE public.admin_recipes SET ingredients_ru = '["Фарш (говяжий или куриный): 300 г", "Рис: половина стакана", "Укроп: 2 больших пучка", "Картофель: 2 шт.", "Лук: 1 шт.", "Соль, перец"]', ingredients_tr = '["Kıyma (dana veya tavuk): 300 g", "Pirinç: yarım bardak", "Dereotu: 2 büyük demet", "Patates: 2 adet", "Soğan: 1 adet", "Tuz, karabiber"]', instructions_ru = '["Смешайте фарш, промытый рис и половину мелко нарезанного укропа", "Добавьте соль и перец, сформируйте кюфту", "Положите нарезанные картофель и лук в кипящую воду", "Через 5 мин добавьте кюфту и варите на слабом огне 25-30 мин", "Незадолго до готовности мелко нарежьте оставшийся укроп и щедро добавьте в суп"]', instructions_tr = '["Kıyma, yıkanmış pirinç ve ince doğranmış dereotunun yarısını karıştırın", "Tuz ve karabiber ekleyip köfteler hazırlayın", "Kaynayan suya doğranmış patates ve soğanı ekleyin", "5 dk sonra köfteleri ekleyip kısık ateşte 25-30 dk pişirin", "Pişmeye yakın kalan dereotunu bolca doğrayıp çorbaya ekleyin"]', ingredients_ar = '["اللحم المفروم (بقري أو دجاج): 300 غ", "الأرز: نصف كوب", "الشبت: حزمتان كبيرتان", "البطاطس: 2 حبة", "البصل: 1 حبة", "الملح والفلفل"]', ingredients_uz = '["Qiymа (mol yoki tovuq go‘shti): 300 g", "Guruch: yarim stakan", "Shivit: 2 katta bog‘lam", "Kartoshka: 2 dona", "Piyoz: 1 dona", "Tuz, murch"]' WHERE id = 'b8788575-43f0-4748-a08b-a02e6044caa7' AND md5(coalesce(ingredients_ru::text,'')) = '4b3197a3b070aba247c3743d230d1be4' AND md5(coalesce(ingredients_tr::text,'')) = '73ae3fd264bd0d0b94dfe3f6a476b3d9' AND md5(coalesce(instructions_ru::text,'')) = 'daace0ea9b9d3533e16a3c98db92f62f' AND md5(coalesce(instructions_tr::text,'')) = '8773cb5025a61f374808682512271b82' AND md5(coalesce(ingredients_ar::text,'')) = 'bb710a33204abd1c952b4dcb967aab49' AND md5(coalesce(ingredients_uz::text,'')) = '60f9bfadc50a0bf118a820d52704055d';
