UPDATE public.admin_recipes SET ingredients_ru = '["Лосось: 150 г", "Спаржа или стручковая фасоль: 100 г", "Лимон: половина", "Укроп: 1 пучок", "Оливковое масло: 1 столовая ложка"]', ingredients_tr = '["Somon: 150 g", "Kuşkonmaz veya Yeşil fasulye: 100 g", "Limon: yarım adet", "Dereotu: 1 demet", "Zeytinyağı: 1 yemek kaşığı"]', ingredients_kk = '["Албырт (сомон): 150 г", "Қояншөп немесе жасыл үрмебұршақ: 100 г", "Лимон: жарты дана", "Аскөк: 1 бума", "Зәйтүн майы: 1 ас қасық"]', instructions_kk = '["Балыққа тұз сеуіп, лимон шырынына маринадтаңыз (10 мин)", "Көкөністерді балықтың жанына орналастырыңыз", "Үстіне зәйтүн майын жағып, фольгаға ораңыз", "Пеште 180°C температурада 20 минут пісіріңіз", "Үстіне балғын аскөкті молынан себіңіз"]', ingredients_de = '["Lachs: 150 g", "Spargel oder grüne Bohnen: 100 g", "Zitrone: eine halbe", "Dill: 1 Bund", "Olivenöl: 1 Esslöffel"]', instructions_de = '["Salze den Fisch und mariniere ihn mit Zitronensaft (10 Min.)", "Lege das Gemüse daneben", "Beträufle alles mit Olivenöl und wickle es in Folie ein", "Im Backofen bei 180°C 20 Minuten garen", "Mit reichlich frischem Dill bestreuen – unterstützt den Milchfluss"]', ingredients_ka = '["ორაგული (სალმონი): 150 გ", "სატაცური ან მწვანე ლობიო: 100 გ", "ლიმონი: ნახევარი", "კამა: 1 კონა", "ზეითუნის ზეთი: 1 სუფრის კოვზი"]', instructions_ka = '["თევზს მოაყარეთ მარილი და ლიმონის წვენში დაამარინადეთ (10 წთ)", "გვერდით ბოსტნეული დაალაგეთ", "წაუსვით ზეითუნის ზეთი და ფოლგაში გაახვიეთ", "ღუმელში 180°C-ზე 20 წუთის განმავლობაში მოამზადეთ", "ზემოდან უხვად მოაყარეთ ახალი კამა — ის ტრადიციულად ლაქტაციის ხელშემწყობად მიიჩნევა"]' WHERE id = 'fe3cad51-3e25-4969-b2ba-dbb221d883b9' AND md5(coalesce(ingredients_ru::text,'')) = 'd446bdcf2b61b3542513828736a37523' AND md5(coalesce(ingredients_tr::text,'')) = 'b1553748efa62f27bf5e2ae88ef0752c' AND md5(coalesce(ingredients_kk::text,'')) = '72ede16148b4d0772de3c6828f1fa2a2' AND md5(coalesce(instructions_kk::text,'')) = '275db1a3f8c25c556290c529de2392d7' AND md5(coa