UPDATE public.pregnancy_day_notifications SET body_kk = 'Шамамен 18-20 см. Енді мені басымнан аяғыма дейін өлшейді. Бойым өсіп, денем қалыптасып келеді.', body_de = 'Ungefähr 18-20 cm. Jetzt werde ich vom Kopf bis zu den Füßen gemessen. Ich werde länger und mein Körper richtet sich auf.' WHERE id = '6fb4f290-31ce-473d-a17d-ea607c5d055d' AND md5(coalesce(body_kk::text,'')) = 'a000e38ec2877f4f3bbe3cb83abe68a4' AND md5(coalesce(body_de::text,'')) = '2970e7700d6127071f6baa9f1cd0e0a5';
