' AND ingredients_ru = '["Гречка - 2 столовые ложки", "Говядина - 30 г", "Морковь - половина"]'::jsonb AND ingredients_tr = '["Karabuğday - 2 yemek kaşığı", "Dana eti - 30 g", "Havuç - yarım adet"]'::jsonb AND ingredients_kk = '["Қарақұмық - 2 ас қасық", "Сиыр еті - 30 г", "Сәбіз - жарты дана"]'::jsonb AND ingredients_uz = '["Grechka - 2 osh qoshiq", "Mol go‘shti - 30 g", "Sabzi - yarim dona"]'::jsonb) + (SELECT count(*) FROM public.admin_recipes WHERE id = '228f023f-d713-4f19-be8e-fefdb4fed98b' AND ingredients_ru = '["Куриное филе - 150 г", "Разноцветный сладкий перец - 1 штука", "Морковь - 1 штука", "Соевый соус - 1 столовая ложка", "Кунжут - 1 чайная ложка", "Оливковое масло"]'::jsonb AND ingredients_tr = '["Tavuk fileto - 150 g", "Renkli biber - 1 adet", "Havuç - 1 adet", "Soya sosu - 1 yemek kaşığı", "Susam - 1 çay kaşığı", "Zeytinyağı"]'::jsonb AND ingredients_de = '["Hähnchenfilet - 150 g", "Bunte Paprika - 1 Stück", "Karotte - 1 Stück", "Sojasauce - 1 Esslöffel", "Sesam - 1 Teelöffel", "Olivenöl"]'::jsonb AND ingredients_uz = '["Tovuq filesi - 150 g", "Rangli bulg‘or qalampiri - 1 dona", "Sabzi - 1 dona", "Soya sousi - 1 osh qoshiq", "Kunjut - 1 choy qoshiq", "Zaytun moyi"]'::jsonb AND ingredients_ka = '["ქათმის ფილე - 150 გ", "ფერადი ბულგარული წიწაკა - 1 ცალი", "სტაფილო - 1 ცალი", "სოიოს სოუსი - 1 სუფრის კოვზი", "სეზამი - 1 ჩაის კოვზი", "ზეითუნის ზეთი"]'::jsonb) + (SELECT count(*) FROM public.admin_recipes WHERE id = '2369413b-697e-4e19-93a2-ff9c61cde8f7' AND ingredients_ru = '["Нежирный говяжий фарш: 150 г", "Цукини и морковь: по четверти каждого (очень мелко натёртые и отжатые)", "Лук: очень маленький кусочек (натёртый)", "Оливковое масло."]'::jsonb AND ingredients_tr = '["Yağsız dana kıyma: 150 g", "Kabak ve havuç: Her birinden dörtte bir adet (çok ince rendelenmiş ve suyu sıkılmış)", "Soğan: Çok küçük bir parça (rendelenmiş)", "Zeytinyağı."]'::jsonb AND ingredients_kk = '["Майсыз тартылған сиыр еті: 150 г", "Кәді мен сәбіз: Әрқайсысының төрттен бірі (өт